; EXODUS.BIN: Ultima III (Origin 1983, PC version by James R. Van Artsdalen).
; Generated by tools/gen.py; tools/build.py builds it (MASM, LINK, then the image from 0100).
; COMBAT: fights (888B-941E).
;
; The whole fight. Entry points: CmdAttack (CmdAttack, the surface A command), FightCreature (FightCreature,
; also when a creature attacks the party: WORLD 23D0) and StartCombat (StartCombat, a dungeon's
; wandering monster, with FoeTile set). StartCombat picks a CNFLCT map by terrain and foe, loads
; it over StartUp, saves Location (in SavedLocation) and sets Location = 80h, places the party and 1-8
; foes, then loops: CombatRound / PlayerTurn (a key through CombatKeys/CombatCmds in CMDTAB, a
; Pass after 5 seconds) / PlayerTurnEnd for each player, then FoesTurn (move, melee, a dragon's
; fire, magic), until every foe is dead (Victory) or the party (PARTY 6C29 ends the game). There
; is no fleeing: a move off the 11 x 11 map is refused. MainLoop jumps to PlayerTurnEnd while
; Location = 80h, so a handler that ends in MainLoop (Volume, "What?") spends the turn.
; The combat arrays are the CNFLCT file's tail in StartUp's memory (docs/FORMATS.md 5 and 9),
; written StartUp+offset, or Ofs80h ... CmbPlrTile (EXDATA labels at those offsets) indexed by a
; register holding StartUp + slot:
;   StartUp+80h foe x [8], +88h foe y, +90h the tile under the foe, +98h foe hit points (0 dead),
;   StartUp+A0h player x [4] (0FFh dead), +A4h player y, +A8h the tile under him, +ACh his tile.
; FoeTile is the foes' shape number, HitTile the flash tile, CombatPlayer
; whose turn it is. Foe = a combat monster here; the map's creatures are the Mon arrays.
CODE SEGMENT BYTE PUBLIC
ASSUME CS:CODE, DS:CODE, ES:CODE, SS:CODE
EXTRN BlinkCount:BYTE
EXTRN PutChar:NEAR
EXTRN Random:NEAR
EXTRN KeyReady:NEAR
EXTRN ReadKey:NEAR
EXTRN PrintBcdByte:NEAR
EXTRN PrintDigit:NEAR
EXTRN LoadFile:NEAR
EXTRN SignStep:NEAR
EXTRN DrawView:NEAR
EXTRN ViewTileAt:NEAR
EXTRN Sound:NEAR
EXTRN Ofs80h:BYTE
EXTRN CmbMonY:BYTE
EXTRN CmbMonUnder:BYTE
EXTRN CmbMonHP:BYTE
EXTRN CmbPlrX:BYTE
EXTRN CmbPlrY:BYTE
EXTRN CmbPlrUnder:BYTE
EXTRN CmbPlrTile:BYTE
EXTRN MonTile:BYTE
EXTRN MonUnder:BYTE
EXTRN MonX:BYTE
EXTRN MonY:BYTE
EXTRN PartyTile:BYTE
EXTRN Location:BYTE
EXTRN PartySize:BYTE
EXTRN Players:BYTE
EXTRN PlrStatus:BYTE
EXTRN PlayerXY:BYTE
EXTRN PlayerY:BYTE
EXTRN TimeStop:BYTE
EXTRN MsgVolume:BYTE
EXTRN MsgMoveNorth:BYTE
EXTRN MsgMoveSouth:BYTE
EXTRN MsgMoveEast:BYTE
EXTRN MsgMoveWest:BYTE
EXTRN MainLoop:NEAR
EXTRN CmdVolume:NEAR
EXTRN StartUp:NEAR
EXTRN TileHere:BYTE
EXTRN PrintMsg:NEAR
EXTRN ScrollMsg:NEAR
EXTRN BuildView:NEAR
EXTRN MapCellAddr:NEAR
EXTRN SavedLocation:BYTE
EXTRN InExodusCastle:NEAR
EXTRN AddExp:NEAR
EXTRN CastSpell:NEAR
EXTRN HurtPlayer:NEAR
EXTRN PrintName:NEAR
EXTRN IsUp:NEAR
EXTRN CheckAllOut:NEAR
EXTRN FlushKeys:NEAR
EXTRN StatusLine:NEAR
EXTRN ShowZtats:NEAR
EXTRN PartyUpkeep:NEAR
EXTRN FlashPlayer:NEAR
EXTRN FlashView:NEAR
EXTRN InvertPlayerNum:NEAR
EXTRN AskDirection:NEAR
EXTRN MsgNoneLeft:NEAR
EXTRN MsgWhat:NEAR
EXTRN MsgInvalidMove:NEAR
EXTRN MsgNotHere:NEAR
EXTRN AddMoves:NEAR
EXTRN ReadyWeapon:NEAR
EXTRN FindMonster:NEAR
EXTRN HitTile:BYTE
EXTRN CombatPlayer:BYTE
EXTRN FoeTile:BYTE
EXTRN KillSpellUsed:BYTE
EXTRN FileConflictA:BYTE
EXTRN FileConflictB:BYTE
EXTRN FileConflictC:BYTE
EXTRN FileConflictF:BYTE
EXTRN FileConflict:BYTE
EXTRN FileConflictM:BYTE
EXTRN FileConflictQ:BYTE
EXTRN FileConflictR:BYTE
EXTRN FileConflictS:BYTE
EXTRN CombatKeys:BYTE
EXTRN CombatCmds:BYTE
EXTRN FoeHitPoints:BYTE
EXTRN FoeExp:BYTE
EXTRN CombatClassLetters:BYTE
EXTRN CombatClassTiles:BYTE
EXTRN MsgPlrKilled:BYTE
EXTRN MsgPlrPoisoned:BYTE
EXTRN MsgPlrN:BYTE
EXTRN MsgPlrPilfered:BYTE
EXTRN MsgFoeMissed:BYTE
EXTRN MsgFoeHit:BYTE
EXTRN MsgThieves:BYTE
EXTRN MsgPluralE:BYTE
EXTRN MsgPluralS:BYTE
EXTRN MsgConflict:BYTE
EXTRN MsgPlayerBar:BYTE
EXTRN MsgBarEnd:BYTE
EXTRN MsgAttackDir:BYTE
EXTRN MsgAttackMissed:BYTE
EXTRN MsgAttackHit:BYTE
EXTRN MsgKilledExp:BYTE
EXTRN MsgCombatReady:BYTE
EXTRN MsgCombatCast:BYTE
EXTRN MsgCombatNegate:BYTE
EXTRN MsgNotUsableCmd:BYTE
EXTRN MsgCombatZtats:BYTE
EXTRN MsgVictory:BYTE
EXTRN MsgCombatPass:BYTE
PUBLIC CmdAttack
PUBLIC FightCreature
PUBLIC StartCombat
PUBLIC PlayerTurnEnd
PUBLIC CCmdNorth
PUBLIC CCmdSouth
PUBLIC CCmdEast
PUBLIC CCmdWest
PUBLIC CCmdVolume
PUBLIC CCmdReady
PUBLIC CCmdZtats
PUBLIC CCmdCast
PUBLIC CCmdNegate
PUBLIC CCmdPass
PUBLIC CCmdBad
PUBLIC CCmdAttack
PUBLIC ShootLine
PUBLIC DamageFoe
;------------------------------------------------------------------------------
; CmdAttack: surface A. Asks a direction (HAND 7AEA: ZF Esc, BX = the cell), finds
; the creature there (EQUIP 7F96: BX = slot or 0FFFFh) and fights it.
;------------------------------------------------------------------------------
CmdAttack:	call PrintMsg	;@888B
	mov byte ptr HitTile, 3Dh	; HitTile = fire	;@888E
	call AskDirection	; AskDirection: BX = target cell	;@8893
	je Attack_Cancel	;@8896
	mov dx, bx	;@8898
	call FindMonster	; BX = creature slot or 0FFFFh	;@889A
	cmp bx, -1	;@889D
	je Attack_NotHere	;@88A0
	jmp short FightCreature	;@88A2
Attack_NotHere:	jmp MsgNotHere	;@88A4
Attack_Cancel:	jmp MainLoop	;@88A7
;------------------------------------------------------------------------------
; FightCreature: fight creature slot BX (0-31). Its map cell becomes a chest standing on
; what the creature stood on (MonUnder holds the map byte under a creature: 04h grass -> 25h,
; ...; floor -> 24h), or stays water for a sea creature; an attacked pirate ship seen from land
; is left as an empty frigate (2Ch). The slot is freed and FoeTile = its shape number.
;------------------------------------------------------------------------------
FightCreature:	call BuildView	;@88AA
	mov di, bx	; DI = creature slot	;@88AD
	mov bh, byte ptr MonY[di]	;@88AF
	mov bl, byte ptr MonX[di]	;@88B3
	call MapCellAddr	;@88B7
	mov al, byte ptr MonUnder[di]	; the map byte under the creature	;@88BA
	cmp al, 0	; 0 (water): leave water	;@88BE
	je FightCreature_Leave	;@88C0
	shr al, 1	; shape 1-3 (grass, brush, forest), floor 0	;@88C2
	shr al, 1	;@88C4
	and al, 3	;@88C6
	or al, 24h	; a chest (24h-27h) on that ground	;@88C8
FightCreature_Leave:	mov byte ptr [bx], al	; the cell left behind	;@88CA
	mov al, byte ptr MonTile[di]	; creature tile ...	;@88CC
	shr al, 1	;@88D0
	shr al, 1	;@88D2
	mov byte ptr FoeTile, al	; ... / 4 = FoeTile	;@88D4
	mov byte ptr MonTile[di], 0	; the creature is gone from the map	;@88D7
	cmp al, 0Fh	; Pirate?	;@88DC
	jne StartCombat	;@88DE
	cmp byte ptr PartyTile, 0Bh	; party on a frigate?	;@88E0
	je StartCombat	;@88E5
	mov byte ptr [bx], 2Ch	; no: the pirates' frigate (shape 11) stays	;@88E7
;------------------------------------------------------------------------------
; StartCombat: fight FoeTile. Guards and Lord British on the map stop talking (MonTalk
; 0C0h); "---Conflict!!---" and the foes' plural name; then the CNFLCT map:
;   in a dungeon C; Pirates (become Thieves): S from a frigate, A from land; from a frigate Q
;   for sea foes (< 10h), R for the others; sea foes (0Bh-0Fh) from land M; else by the tile
;   under the party (TileHere): grass G, brush B, forest F, floor C (a chest on floor too), force
;   field or lava C, FoeTile 8 C, anything else G.
;------------------------------------------------------------------------------
StartCombat:	mov byte ptr KillSpellUsed, 0	; the orc/skeleton spells work again	;@88EA
	lea bx, MonTile	;@88EF
	mov cx, 20h	;@88F3
StartCombat_Guards:	cmp byte ptr [bx], 4Ch	; Lord British?	;@88F6
	je StartCombat_Hostile	;@88F9
	cmp byte ptr [bx], 48h	; Guard?	;@88FB
	jne StartCombat_NextSlot	;@88FE
StartCombat_Hostile:	mov byte ptr Ofs80h[bx], 0C0h	; MonTile+80h = MonTalk: 0C0h, no more talking	;@8900
StartCombat_NextSlot:	inc bx	;@8905
	loop StartCombat_Guards	;@8906
	lea si, MsgConflict	; "---Conflict!!---" "->"	;@8908
	call PrintMsg	;@890C
	mov al, 0FFh	; plural	;@890F
	call PrintFoeName	;@8911
	call ScrollMsg	;@8914
	call ScrollMsg	;@8917
	cmp byte ptr Location, 1	; in a dungeon?	;@891A
	jne StartCombat_TryPirate	;@891F
	lea dx, FileConflictC	; CNFLCT_C	;@8921
	jmp StartCombat_Load	;@8925
StartCombat_TryPirate:	cmp byte ptr FoeTile, 0Fh	; Pirate?	;@8928
	jne StartCombat_TryShip	;@892D
	mov byte ptr FoeTile, 17h	; fought as Thieves	;@892F
	lea dx, FileConflictS	; CNFLCT_S	;@8934
	cmp byte ptr PartyTile, 0Bh	; party on a frigate?	;@8938
	jne StartCombat_Ashore	;@893D
	jmp StartCombat_Load	;@893F
StartCombat_Ashore:	lea dx, FileConflictA	; CNFLCT_A	;@8942
	jmp short StartCombat_Load	;@8946
StartCombat_TryShip:	cmp byte ptr PartyTile, 0Bh	; party on a frigate?	;@8948
	jne StartCombat_TrySea	;@894D
	lea dx, FileConflictQ	; CNFLCT_Q: sea foe	;@894F
	cmp byte ptr FoeTile, 10h	;@8953
	jb StartCombat_Load	;@8958
	lea dx, FileConflictR	; CNFLCT_R: land foe	;@895A
	jmp short StartCombat_Load	;@895E
StartCombat_TrySea:	cmp byte ptr FoeTile, 10h	; sea foe (0Bh-0Fh) ...	;@8960
	jae StartCombat_Terrain	;@8965
	lea dx, FileConflictM	; CNFLCT_M	;@8967
	cmp byte ptr FoeTile, 0Bh	;@896B
	jae StartCombat_Load	;@8970
StartCombat_Terrain:	mov al, byte ptr TileHere	; the tile under the party	;@8972
	cmp al, 9	; a chest?	;@8975
	jne StartCombat_TryGrass	;@8977
	mov bx, word ptr PlayerXY	;@8979
	call MapCellAddr	;@897D
	and al, 3	; low bits 0: on floor	;@8980
	jne StartCombat_TryGrass	;@8982
	mov al, 8	; treat as floor	;@8984
StartCombat_TryGrass:	lea dx, FileConflict	; CNFLCT_G	;@8986
	cmp al, 1	; grass	;@898A
	je StartCombat_Load	;@898C
	lea dx, FileConflictB	; CNFLCT_B	;@898E
	cmp al, 2	; brush	;@8992
	je StartCombat_Load	;@8994
	lea dx, FileConflictF	; CNFLCT_F	;@8996
	cmp al, 3	; forest	;@899A
	je StartCombat_Load	;@899C
	lea dx, FileConflictC	; CNFLCT_C	;@899E
	cmp al, 8	; floor	;@89A2
	je StartCombat_Load	;@89A4
	cmp al, 20h	; force field	;@89A6
	je StartCombat_Load	;@89A8
	cmp al, 21h	; lava	;@89AA
	je StartCombat_Load	;@89AC
	lea dx, FileConflictC	;@89AE
	cmp byte ptr FoeTile, 8	; FoeTile 8 (floor?)	;@89B2
	je StartCombat_Load	;@89B7
	lea dx, FileConflict	; CNFLCT_G	;@89B9
StartCombat_Load:	lea bx, StartUp	; the combat map over StartUp	;@89BD
	mov cx, 0B0h	;@89C1
	call LoadFile	;@89C4
	mov al, byte ptr Location	;@89C7
	mov byte ptr SavedLocation, al	; keep the Location for after the fight	;@89CA
	mov byte ptr Location, 80h	; 80h: in a fight	;@89CD
; Place the party, last player first: DI = StartUp + slot, SI = his record. A player who is up
; stands where the file says (+A0h/+A4h) with his class's tile (+ACh); +A8h keeps what he
; covers. The others get position 0FFh (off the map).
	mov al, byte ptr PartySize	;@89D2
	mov ah, 0	;@89D5
	mov di, ax	;@89D7
	dec di	;@89D9
	mov cx, ax	;@89DA
	lea di, StartUp[di]	;@89DC
	dec al	;@89E0
	mov ah, 40h	;@89E2
	mul ah	;@89E4
	mov si, ax	;@89E6
	lea si, Players[si]	;@89E8
StartCombat_PlacePlr:	cmp byte ptr [si+11h], 47h	; status 'G'	;@89EC
	je StartCombat_PlrUp	;@89F0
	cmp byte ptr [si+11h], 50h	; status 'P'	;@89F2
	je StartCombat_PlrUp	;@89F6
	mov byte ptr CmbPlrX[di], 0FFh	; player x = 0FFh: not in the fight	;@89F8
	mov byte ptr CmbPlrY[di], 0FFh	;@89FD
	jmp short StartCombat_NextPlr	;@8A02
StartCombat_PlrUp:	mov bl, byte ptr CmbPlrX[di]	; player x, y from the file	;@8A04
	mov bh, byte ptr CmbPlrY[di]	;@8A08
	mov al, byte ptr [si+17h]	; class letter	;@8A0C
	call ClassTile	; AL = his tile	;@8A0F
	mov byte ptr CmbPlrTile[di], al	; player tile	;@8A12
	call ViewTileAt	; BX = view cell, AL = what is there	;@8A16
	mov byte ptr CmbPlrUnder[di], al	; tile under him	;@8A19
	mov al, byte ptr CmbPlrTile[di]	;@8A1D
	mov byte ptr [bx], al	; draw him	;@8A21
StartCombat_NextPlr:	sub si, 40h	;@8A23
	dec di	;@8A26
	loop StartCombat_PlacePlr	;@8A27
	cld	;@8A29
	lea di, StartUp+98h	; all foes dead to start with (hit points)	;@8A2A
	mov cx, 8	;@8A2E
	mov al, 0	;@8A31
	rep stosb	;@8A33
; How many foes: 8 in the castle of Exodus (ITEMS 5B28 ZF set); in a town or castle (Location
; 2 or more, not Ambrosia) 1, or 8 Guards; else (Sosaria, dungeon, Ambrosia) 1-8 at random.
	call InExodusCastle	; ZF: Exodus's castle	;@8A35
	je StartCombat_Eight	;@8A38
	cmp byte ptr SavedLocation, 2	; came from a town/castle?	;@8A3A
	jb StartCombat_RandCount	;@8A3F
	cmp byte ptr SavedLocation, 0FFh	; Ambrosia	;@8A41
	je StartCombat_RandCount	;@8A46
	cmp byte ptr FoeTile, 12h	; Guards come eight	;@8A48
	je StartCombat_Eight	;@8A4D
	mov cx, 1	;@8A4F
	jmp short StartCombat_PlaceFoe	;@8A52
StartCombat_Eight:	mov cx, 8	;@8A54
	jmp short StartCombat_PlaceFoe	;@8A57
StartCombat_RandCount:	mov dh, 8	;@8A59
	call Random	; 1-8	;@8A5B
	inc dl	;@8A5E
	mov cl, dl	;@8A60
	mov ch, 0	;@8A62
StartCombat_PlaceFoe:	mov dh, 8	; a random free slot 0-7	;@8A64
	call Random	;@8A66
	mov bl, dl	;@8A69
	mov bh, 0	;@8A6B
	mov si, bx	;@8A6D
	lea si, StartUp[si]	;@8A6F
	cmp byte ptr CmbMonHP[si], 0	; foe hit points: 0 = free	;@8A73
	jne StartCombat_PlaceFoe	;@8A78
	mov bl, byte ptr FoeTile	;@8A7A
	and bl, 0Fh	; by FoeTile & 0Fh	;@8A7E
	mov dh, byte ptr FoeHitPoints[bx]	;@8A81
	call Random	; Random(FoeHitPoints[...])	;@8A85
	or dl, 0Fh	; at least 0Fh	;@8A88
	mov byte ptr CmbMonHP[si], dl	; foe hit points	;@8A8B
	mov bh, byte ptr CmbMonY[si]	; foe x, y from the file	;@8A8F
	mov bl, byte ptr Ofs80h[si]	;@8A93
	call ViewTileAt	; BX = view cell, AL = what is there	;@8A97
	mov byte ptr CmbMonUnder[si], al	; tile under the foe	;@8A9A
	mov al, byte ptr FoeTile	;@8A9E
	mov byte ptr [bx], al	; draw the foe	;@8AA1
	loop StartCombat_PlaceFoe	;@8AA3
	call DrawView	;@8AA5
	mov al, 0FDh	; warble: the fanfare (BL, BH: its notes?)	;@8AA8
	mov bl, 0F0h	;@8AAA
	mov bh, 10h	;@8AAC
	call Sound	;@8AAE
	call Sound	;@8AB1
	mov bh, 4	;@8AB4
	call Sound	;@8AB6
	mov bh, 10h	;@8AB9
	call Sound	;@8ABB
	call FlushKeys	;@8ABE
	jmp CombatRound	;@8AC1
;------------------------------------------------------------------------------
; ClassTile: AL = class letter -> AL = the tile that shows that class in a fight (CMDTAB
; CombatClassLetters / CombatClassTiles); 3Fh (Ranger) for a class not listed.
;------------------------------------------------------------------------------
ClassTile:	pushf	;@8AC4
	push bx	;@8AC5
	push cx	;@8AC6
	push di	;@8AC7
	cld	;@8AC8
	mov cx, 0Ah	;@8AC9
	mov bx, cx	;@8ACC
	lea di, CombatClassLetters	;@8ACE
	repne scasb	;@8AD2
	jne ClassTile_Default	;@8AD4
	sub bx, cx	;@8AD6
	dec bx	;@8AD8
	mov al, byte ptr CombatClassTiles[bx]	; the class's tile	;@8AD9
ClassTile_Done:	pop di	;@8ADD
	pop cx	;@8ADE
	pop bx	;@8ADF
	popf	;@8AE0
	ret	;@8AE1
ClassTile_Default:	mov al, 3Fh	; Ranger	;@8AE2
	jmp ClassTile_Done	;@8AE4
;------------------------------------------------------------------------------
; PrintFoeName: print the name of the foes. AL = 0FFh the plural (the "Conflict" banner), 0 the
; singular. Normally the shape name (NameTbl FoeTile); for Thief ... Balron (17h-1Eh) when the
; party's y is odd one of the 16 monster names instead, two a kind chosen by x's low bit (Thief:
; Brigand/Cutpurse, Orc: Goblin/Troll, ..., Balron: Orcus/Devil). The plural adds "s" ("es"
; for Snatch), except for names 1, 8, 13h, 86h (Grass?, Floor?, Lord British, Orcus); "Thieves"
; is a string of its own. Saves flags, AX, SI.
;------------------------------------------------------------------------------
PrintFoeName:	pushf	;@8AE6
	push ax	;@8AE7
	push si	;@8AE8
	mov ah, al	; AH = the plural flag	;@8AE9
	mov al, byte ptr PlayerY	; party y ...	;@8AEB
	shr al, 1	; ... odd?	;@8AEE
	jae PrintFoeName_Plain	;@8AF0
	mov al, byte ptr FoeTile	;@8AF2
	sub al, 17h	; 17h-1Eh only	;@8AF5
	jb PrintFoeName_Plain	;@8AF7
	push ax	;@8AF9
	mov ah, byte ptr PlayerXY	;@8AFA
	shr ah, 1	; x's low bit into CF	;@8AFE
	pop ax	;@8B00
	rcl al, 1	; 2 * (kind - 17h) + (x & 1)	;@8B01
	add al, 79h	; name 120 + that (Brigand ...)	;@8B03
	call PrintName	; prints name AL-1	;@8B05
PrintFoeName_Plural:	cmp ah, 0FFh	;@8B08
	jne PrintFoeName_Done	;@8B0B
	cmp al, 2	; AL = name + 1: Grass?	;@8B0D
	je PrintFoeName_Scroll	;@8B0F
	cmp al, 9	; Floor?	;@8B11
	je PrintFoeName_Scroll	;@8B13
	cmp al, 14h	; Lord British	;@8B15
	je PrintFoeName_Scroll	;@8B17
	cmp al, 87h	; Orcus	;@8B19
	je PrintFoeName_Scroll	;@8B1B
	lea si, MsgPluralE	; "e" "s"	;@8B1D
	cmp al, 83h	; Snatch	;@8B21
	je PrintFoeName_Suffix	;@8B23
	lea si, MsgPluralS	; "s"	;@8B25
PrintFoeName_Suffix:	call PrintMsg	;@8B29
PrintFoeName_Done:	pop si	;@8B2C
	pop ax	;@8B2D
	popf	;@8B2E
	ret	;@8B2F
PrintFoeName_Plain:	mov al, byte ptr FoeTile	;@8B30
	cmp al, 17h	; Thief?	;@8B33
	je PrintFoeName_Thief	;@8B35
PrintFoeName_Shape:	add al, 1	; the shape's name	;@8B37
	call PrintName	;@8B39
	jmp PrintFoeName_Plural	;@8B3C
PrintFoeName_Thief:	cmp ah, 0FFh	;@8B3E
	jne PrintFoeName_Shape	;@8B41
	lea si, MsgThieves	; "Thieves"	;@8B43
	call PrintMsg	;@8B47
PrintFoeName_Scroll:	call ScrollMsg	;@8B4A
	call ScrollMsg	;@8B4D
	jmp PrintFoeName_Done	;@8B50
;------------------------------------------------------------------------------
; CombatRound: a round: food is eaten as for a step (PARTY 6FDF), then each player's turn from
; the first.
;------------------------------------------------------------------------------
CombatRound:	call PartyUpkeep	;@8B52
	mov byte ptr CombatPlayer, 0	; CombatPlayer = 0	;@8B55
;------------------------------------------------------------------------------
; PlayerTurn: CombatPlayer's turn: his status line inverted (PARTY 71ED), "----Player n----",
; then a key; with none for 5 seconds his tile is put back (the blink may have left the floor)
; and he passes. The key, upper-cased, is looked up in CombatKeys and CombatCmds is jumped
; through (SI is not set: the handlers load their own message).
;------------------------------------------------------------------------------
PlayerTurn:	mov al, byte ptr CombatPlayer	;@8B5A
	inc al	;@8B5D
	call InvertPlayerNum	; highlight his status line (AL = 1-4)	;@8B5F
	mov ah, 40h	;@8B62
	dec al	;@8B64
	mul ah	;@8B66
	mov bx, ax	;@8B68
	lea bx, Players[bx]	; BX = his record	;@8B6A
	call IsUp	; not up: next player	;@8B6E
	je PlayerTurn_Banner	;@8B71
	jmp PlayerTurnEnd	;@8B73
PlayerTurn_Banner:	lea si, MsgPlayerBar	; "----Player "	;@8B76
	call PrintMsg	;@8B7A
	mov al, byte ptr CombatPlayer	;@8B7D
	inc al	;@8B80
	call PrintDigit	; n	;@8B82
	lea si, MsgBarEnd	; "----"	;@8B85
	call PrintMsg	;@8B89
PlayerTurn_Prompt:	mov al, 10h	; the prompt character	;@8B8C
	call PutChar	;@8B8E
	mov byte ptr BlinkCount, 2	; the library blinks his tile (K2928)	;@8B91
	mov ah, 2Ch	; DOS get time: DH = seconds	;@8B96
	int 21h	;@8B98
	mov bl, dh	;@8B9A
	add bl, 5	; 5 seconds from now	;@8B9C
	cmp bl, 3Ch	;@8B9F
	jb PlayerTurn_Wait	;@8BA2
	sub bl, 3Ch	;@8BA4
PlayerTurn_Wait:	call KeyReady	; key waiting?	;@8BA7
	jne PlayerTurn_Key	;@8BAA
	mov ah, 2Ch	;@8BAC
	int 21h	;@8BAE
	cmp bl, dh	;@8BB0
	jne PlayerTurn_Wait	;@8BB2
	mov bl, byte ptr CombatPlayer	; timeout: his tile back on the map	;@8BB4
	mov bh, 0	;@8BB8
	mov ah, byte ptr StartUp+0ACh[bx]	; player tile	;@8BBA
	mov al, byte ptr StartUp+0A4h[bx]	; player y	;@8BBE
	mov bl, byte ptr StartUp+0A0h[bx]	; player x	;@8BC2
	mov bh, al	;@8BC6
	call ViewTileAt	;@8BC8
	mov byte ptr [bx], ah	;@8BCB
	call DrawView	;@8BCD
	mov ax, 3920h	; Space = Pass	;@8BD0
	jmp short PlayerTurn_Find	;@8BD3
PlayerTurn_Key:	call ReadKey	;@8BD5
	cmp al, 61h	; 'a'-'z' -> 'A'-'Z'	;@8BD8
	jb PlayerTurn_Find	;@8BDA
	cmp al, 7Ah	;@8BDC
	ja PlayerTurn_Find	;@8BDE
	sub al, 20h	;@8BE0
PlayerTurn_Find:	mov cx, 21h	; 33 keys	;@8BE2
	lea di, CombatKeys	;@8BE5
	repne scasw	; search the key word	;@8BE9
	je PlayerTurn_Found	;@8BEB
	jmp MsgWhat	;@8BED
PlayerTurn_Found:	mov bx, 21h	; BX = entry * 2	;@8BF0
	sub bx, cx	;@8BF3
	dec bx	;@8BF5
	shl bx, 1	;@8BF6
	jmp word ptr CombatCmds[bx]	;@8BF8
;------------------------------------------------------------------------------
; PlayerTurnEnd: every combat command ends here (and MainLoop jumps here in a fight).
; One move more; Negate Time does nothing in the castle of Exodus; the status line back to
; normal; Victory when all foes are dead, else the next player, or the foes after the last.
;------------------------------------------------------------------------------
PlayerTurnEnd:	mov al, 1	;@8BFC
	call AddMoves	; one move	;@8BFE
	call InExodusCastle	; ZF: Exodus's castle	;@8C01
	jne PlayerTurnEnd_Check	;@8C04
	mov byte ptr TimeStop, 0	; no Negate Time there	;@8C06
PlayerTurnEnd_Check:	mov al, byte ptr CombatPlayer	;@8C0B
	inc al	;@8C0E
	call InvertPlayerNum	; his status line back (toggles)	;@8C10
	mov cx, 8	;@8C13
	lea di, StartUp+98h	; foe hit points: all 0?	;@8C16
	mov al, 0	;@8C1A
	repe scasb	;@8C1C
	je PlayerTurnEnd_Won	;@8C1E
	call DrawView	;@8C20
	call StatusLine	;@8C23
	inc byte ptr CombatPlayer	; next player	;@8C26
	mov al, byte ptr CombatPlayer	;@8C2A
	cmp al, byte ptr PartySize	;@8C2D
	jb PlayerTurnEnd_Next	;@8C31
	jmp FoesTurn	; all have had their turn: the foes	;@8C33
PlayerTurnEnd_Won:	jmp Victory	;@8C36
PlayerTurnEnd_Next:	jmp PlayerTurn	;@8C39
;------------------------------------------------------------------------------
; CCmdMove: move CombatPlayer by DL (x), DH (y) (each -1, 0 or 1); SI = the direction's name.
; Only grass, brush, forest and floor can be entered, and not off the 11 x 11 map.
;------------------------------------------------------------------------------
CCmdMove:	call PrintMsg	;@8C3C
	mov bl, byte ptr CombatPlayer	;@8C3F
	mov bh, 0	;@8C43
	mov si, bx	;@8C45
	lea si, StartUp[si]	; SI = StartUp + player	;@8C47
	mov bh, byte ptr CmbPlrY[si]	; player y	;@8C4B
	mov bl, byte ptr CmbPlrX[si]	; player x	;@8C4F
	mov bp, bx	; BP = where he stands	;@8C53
	add bl, dl	;@8C55
	cmp bl, 0Bh	; off the map? (0FFh too)	;@8C57
	jae CCmdMove_Invalid	;@8C5A
	add bh, dh	;@8C5C
	cmp bh, 0Bh	;@8C5E
	jae CCmdMove_Invalid	;@8C61
	mov cx, bx	; CX = the new cell	;@8C63
	call ViewTileAt	; BX = its view address, AL = tile	;@8C65
	mov ah, al	;@8C68
	call CanWalkOn	; walkable?	;@8C6A
	cmp al, 0FFh	;@8C6D
	je CCmdMove_Invalid	;@8C6F
	mov di, bx	; DI = the new cell's address	;@8C71
	mov bx, bp	;@8C73
	call ViewTileAt	;@8C75
	mov al, byte ptr CmbPlrUnder[si]	; the tile under him ...	;@8C78
	mov byte ptr [bx], al	; ... goes back on the old cell	;@8C7C
	mov byte ptr CmbPlrUnder[si], ah	; the new tile under him	;@8C7E
	mov al, byte ptr CmbPlrTile[si]	; player tile	;@8C82
	mov byte ptr [di], al	;@8C86
	mov byte ptr CmbPlrY[si], ch	; player y	;@8C88
	mov byte ptr CmbPlrX[si], cl	; player x	;@8C8C
	jmp PlayerTurnEnd	;@8C90
CCmdMove_Invalid:	jmp MsgInvalidMove	;@8C93
;------------------------------------------------------------------------------
; CanWalkOn: AL = tile -> AL = 0 when a player may step on it (grass, brush, forest, floor:
; with two tick sounds and a CPU-speed delay between them), else 0FFh.
;------------------------------------------------------------------------------
CanWalkOn:	pushf	;@8C96
	push cx	;@8C97
	cmp al, 1	; grass	;@8C98
	je CanWalkOn_Yes	;@8C9A
	cmp al, 2	; brush	;@8C9C
	je CanWalkOn_Yes	;@8C9E
	cmp al, 3	; forest	;@8CA0
	je CanWalkOn_Yes	;@8CA2
	cmp al, 8	; floor	;@8CA4
	je CanWalkOn_Yes	;@8CA6
	mov al, 0FFh	;@8CA8
CanWalkOn_Done:	pop cx	;@8CAA
	popf	;@8CAB
	ret	;@8CAC
CanWalkOn_Yes:	mov al, 0F6h	; tick sound	;@8CAD
	call Sound	;@8CAF
	mov cx, 2000h	; delay (speed dependent)	;@8CB2
CanWalkOn_Delay:	loop CanWalkOn_Delay	;@8CB5
	call Sound	; again (AL is still 0F6h)	;@8CB7
	mov al, 0	;@8CBA
	jmp CanWalkOn_Done	;@8CBC
;------------------------------------------------------------------------------
; CCmdNorth, CCmdSouth, CCmdEast, CCmdWest: the arrow keys;
; the names "North" ... come from the surface prompts (EXDATA).
;------------------------------------------------------------------------------
CCmdNorth:	lea si, MsgMoveNorth	; "North"	;@8CBE
	mov dh, 0FFh	; y - 1	;@8CC2
	mov dl, 0	;@8CC4
	jmp CCmdMove	;@8CC6
CCmdSouth:	lea si, MsgMoveSouth	; "South"	;@8CC9
	mov dh, 1	;@8CCD
	mov dl, 0	;@8CCF
	jmp CCmdMove	;@8CD1
CCmdEast:	lea si, MsgMoveEast	; "East"	;@8CD4
	mov dh, 0	;@8CD8
	mov dl, 1	;@8CDA
	jmp CCmdMove	;@8CDC
CCmdWest:	lea si, MsgMoveWest	; "West"	;@8CDF
	mov dh, 0	;@8CE3
	mov dl, 0FFh	; x - 1	;@8CE5
	jmp CCmdMove	;@8CE7
;------------------------------------------------------------------------------
; CCmdVolume: V, Alt-S, Alt-V: the surface Volume command (LOOP 2018), which goes back
; through MainLoop, i.e. to PlayerTurnEnd: the turn is spent.
;------------------------------------------------------------------------------
CCmdVolume:	lea si, MsgVolume	; "Volume "	;@8CEA
	jmp CmdVolume	;@8CEE
;------------------------------------------------------------------------------
; CCmdReady: "Ready a weapon!" for CombatPlayer (EQUIP 7E48).
;------------------------------------------------------------------------------
CCmdReady:	lea si, MsgCombatReady	;@8CF1
	call PrintMsg	;@8CF5
	mov al, byte ptr CombatPlayer	;@8CF8
	mov ah, 40h	;@8CFB
	mul ah	;@8CFD
	mov bx, ax	;@8CFF
	lea bx, Players[bx]	;@8D01
	call ReadyWeapon	;@8D05
	jmp PlayerTurnEnd	;@8D08
;------------------------------------------------------------------------------
; CCmdZtats: "Ztats": the Ztats screen of CombatPlayer (PARTY 6DC1), his status line
; highlight taken off meanwhile. The turn is spent.
;------------------------------------------------------------------------------
CCmdZtats:	lea si, MsgCombatZtats	;@8D0B
	call PrintMsg	;@8D0F
	mov al, byte ptr CombatPlayer	;@8D12
	mov dh, al	;@8D15
	add dh, 31h	; DH = '1' + player	;@8D17
	inc al	;@8D1A
	call InvertPlayerNum	; highlight off (toggle)	;@8D1C
	dec al	;@8D1F
	mov ah, 40h	;@8D21
	mul ah	;@8D23
	mov di, ax	;@8D25
	lea di, Players[di]	;@8D27
	call ShowZtats	; Ztats of the record at DI	;@8D2B
	mov al, dh	;@8D2E
	sub al, 30h	;@8D30
	call InvertPlayerNum	; highlight on again	;@8D32
	jmp PlayerTurnEnd	;@8D35
;------------------------------------------------------------------------------
; CCmdCast: "Cast Spell!" for CombatPlayer (MAGIC 5D83), with the magic flash tile.
;------------------------------------------------------------------------------
CCmdCast:	lea si, MsgCombatCast	;@8D38
	call PrintMsg	;@8D3C
	mov byte ptr HitTile, 3Ch	; HitTile = magic (shape 60)	;@8D3F
	mov al, byte ptr CombatPlayer	;@8D44
	mov ah, 40h	;@8D47
	mul ah	;@8D49
	mov bx, ax	;@8D4B
	lea bx, Players[bx]	;@8D4D
	call CastSpell	;@8D51
	jmp PlayerTurnEnd	;@8D54
;------------------------------------------------------------------------------
; CCmdNegate: "Negate Time!": one powder (record 27h, BCD) and the foes miss 10 rounds
; (TimeStop, counted down in FoesTurn); "None left!" without one.
;------------------------------------------------------------------------------
CCmdNegate:	lea si, MsgCombatNegate	;@8D57
	call PrintMsg	;@8D5B
	mov al, byte ptr CombatPlayer	;@8D5E
	mov ah, 40h	;@8D61
	mul ah	;@8D63
	mov bx, ax	;@8D65
	lea bx, Players[bx]	;@8D67
	mov al, byte ptr [bx+27h]	; powders	;@8D6B
	cmp al, 0	;@8D6E
	je CCmdNegate_None	;@8D70
	sub al, 1	;@8D72
	das	;@8D74
	mov byte ptr [bx+27h], al	;@8D75
	mov byte ptr TimeStop, 0Ah	; the foes stop for 10 rounds	;@8D78
	jmp PlayerTurnEnd	;@8D7D
CCmdNegate_None:	jmp MsgNoneLeft	;@8D80
;------------------------------------------------------------------------------
; CCmdPass: "Pass".
;------------------------------------------------------------------------------
CCmdPass:	lea si, MsgCombatPass	;@8D83
	call PrintMsg	;@8D87
	jmp PlayerTurnEnd	;@8D8A
;------------------------------------------------------------------------------
; CCmdBad: every other key: "Not usable cmd!" and the beep; the turn is not spent.
;------------------------------------------------------------------------------
CCmdBad:	lea si, MsgNotUsableCmd	;@8D8D
	call PrintMsg	;@8D91
	mov al, 0FEh	; beep	;@8D94
	call Sound	;@8D96
	call FlushKeys	;@8D99
	jmp PlayerTurn_Prompt	;@8D9C
;------------------------------------------------------------------------------
; CCmdAttack: A: the readied weapon's name, " Attack", "Dir-" and a direction (Esc
; spends the turn). Sling, Bow, +2 Bow and +4 Bow shoot along the direction (ShootLine); the
; others strike the next cell, and a Dagger with no foe there is thrown (one dagger less; with
; none left the player is back to Hand) and flies like an arrow. AttackHit with BX = the foe,
; or "Missed!".
;------------------------------------------------------------------------------
CCmdAttack:	mov byte ptr HitTile, 3Dh	; HitTile = fire	;@8D9F
	mov al, byte ptr CombatPlayer	;@8DA4
	mov ah, 40h	;@8DA7
	mul ah	;@8DA9
	mov si, ax	;@8DAB
	lea si, Players[si]	;@8DAD
	mov al, byte ptr [si+30h]	; weapon readied	;@8DB1
	add al, 41h	; name 40h + weapon: the weapon names	;@8DB4
	call PrintName	;@8DB6
	mov di, si	;@8DB9
	lea si, MsgAttackDir	; " Attack" "Dir-"	;@8DBB
	call PrintMsg	;@8DBF
	mov si, di	;@8DC2
	call AskDirection	; DL, DH = the step; ZF: Esc	;@8DC4
	je CCmdAttack_Cancel	;@8DC7
	mov bl, byte ptr CombatPlayer	;@8DC9
	shl bl, 1	;@8DCD
	shl bl, 1	;@8DCF
	shl bl, 1	;@8DD1
	add bl, 0E0h	; BL = 0E0h + 8 * player: the warble's pitch?	;@8DD3
	mov bh, 6	;@8DD6
	mov al, 0FDh	; warble	;@8DD8
	call Sound	;@8DDA
	mov al, byte ptr [si+30h]	; weapon readied	;@8DDD
	mov bl, byte ptr CombatPlayer	;@8DE0
	mov bh, 0	;@8DE4
	lea bx, StartUp[bx]	; BX = StartUp + player	;@8DE6
	cmp al, 3	; Sling	;@8DEA
	je CCmdAttack_Shoot	;@8DEC
	cmp al, 5	; Bow	;@8DEE
	je CCmdAttack_Shoot	;@8DF0
	cmp al, 9	; +2 Bow	;@8DF2
	je CCmdAttack_Shoot	;@8DF4
	cmp al, 0Dh	; +4 Bow	;@8DF6
	je CCmdAttack_Shoot	;@8DF8
	mov ch, byte ptr CmbPlrY[bx]	; player y	;@8DFA
	mov cl, byte ptr CmbPlrX[bx]	; player x	;@8DFE
	add ch, dh	;@8E02
	add cl, dl	;@8E04
	xchg dx, cx	; DL, DH = the next cell	;@8E06
	mov di, bx	;@8E08
	call FindFoeAt	; a foe there?	;@8E0A
	xchg dx, cx	;@8E0D
	cmp bx, -1	;@8E0F
	jne CCmdAttack_Hit	;@8E12
	mov bx, di	;@8E14
	cmp al, 1	; a Dagger?	;@8E16
	jne CCmdAttack_Miss	;@8E18
	mov al, byte ptr [si+31h]	; thrown: daggers owned (record 31h)	;@8E1A
	sub al, 1	;@8E1D
	das	;@8E1F
	mov byte ptr [si+31h], al	;@8E20
	cmp al, 0	;@8E23
	jne CCmdAttack_Shoot	;@8E25
	mov byte ptr [si+30h], 0	; the last one: readied = Hand	;@8E27
CCmdAttack_Shoot:	mov cx, dx	; CX = the step	;@8E2B
	mov dh, byte ptr CmbPlrY[bx]	; from the player's y ...	;@8E2D
	mov dl, byte ptr CmbPlrX[bx]	; ... and x	;@8E31
	call ShootLine	; BX = foe hit or 0FFFFh	;@8E35
	cmp bx, -1	;@8E38
	je CCmdAttack_Miss	;@8E3B
CCmdAttack_Hit:	jmp AttackHit	;@8E3D
CCmdAttack_Miss:	jmp AttackMissed	;@8E40
CCmdAttack_Cancel:	jmp PlayerTurnEnd	;@8E43
;------------------------------------------------------------------------------
; FindFoeAt: DL = x, DH = y -> BX = the slot (0-7) of the live foe there, or 0FFFFh.
; Saves flags, CX, SI.
;------------------------------------------------------------------------------
FindFoeAt:	pushf	;@8E46
	push cx	;@8E47
	push si	;@8E48
	mov cx, 8	;@8E49
	mov si, 7	;@8E4C
	lea si, StartUp[si]	; SI = StartUp + slot, from the last	;@8E4F
FindFoeAt_Loop:	cmp byte ptr CmbMonHP[si], 0	; foe hit points: alive?	;@8E53
	je FindFoeAt_Next	;@8E58
	cmp byte ptr Ofs80h[si], dl	; foe x	;@8E5A
	jne FindFoeAt_Next	;@8E5E
	cmp byte ptr CmbMonY[si], dh	; foe y	;@8E60
	je FindFoeAt_Found	;@8E64
FindFoeAt_Next:	dec si	;@8E66
	loop FindFoeAt_Loop	;@8E67
	mov bx, 0FFFFh	;@8E69
FindFoeAt_Done:	pop si	;@8E6C
	pop cx	;@8E6D
	popf	;@8E6E
	ret	;@8E6F
FindFoeAt_Found:	lea bx, StartUp	; BX = SI - StartUp: the slot	;@8E70
	sub si, bx	;@8E74
	mov bx, si	;@8E76
	jmp FindFoeAt_Done	;@8E78
;------------------------------------------------------------------------------
; ShootLine: a missile from DL, DH stepping CL, CH, the HitTile flashed on each cell,
; until it meets a foe (BX = slot) or leaves the map (BX = 0FFFFh). Walls and players do not stop
; it. Also used by MAGIC (5F55). Saves flags, AX, DX.
;------------------------------------------------------------------------------
ShootLine:	pushf	;@8E7A
	push ax	;@8E7B
	push dx	;@8E7C
ShootLine_Step:	add dh, ch	;@8E7D
	cmp dh, 0Bh	;@8E7F
	jae ShootLine_Edge	;@8E82
	add dl, cl	;@8E84
	cmp dl, 0Bh	;@8E86
	jae ShootLine_Edge	;@8E89
	mov bx, dx	;@8E8B
	call ViewTileAt	; BX = view address, AL = tile there	;@8E8D
	mov ah, byte ptr HitTile	;@8E90
	mov byte ptr [bx], ah	; the flash ...	;@8E94
	call DrawView	;@8E96
	mov byte ptr [bx], al	; ... and the tile back	;@8E99
	call FindFoeAt	;@8E9B
	cmp bx, -1	;@8E9E
	je ShootLine_Step	;@8EA1
ShootLine_Done:	pop dx	;@8EA3
	pop ax	;@8EA4
	popf	;@8EA5
	ret	;@8EA6
ShootLine_Edge:	call DrawView	;@8EA7
	mov bx, 0FFFFh	;@8EAA
	jmp ShootLine_Done	;@8EAD
; AttackMissed: "Missed!" and the turn ends.
AttackMissed:	lea si, MsgAttackMissed	;@8EAF
	call PrintMsg	;@8EB3
	call DrawView	;@8EB6
	jmp PlayerTurnEnd	;@8EB9
;------------------------------------------------------------------------------
; AttackHit: CombatPlayer's blow reaches foe slot BX. In the castle of Exodus only the Exotic
; weapon hits. Otherwise half the blows hit, the rest when Random(99) < dexterity. Damage:
; weapon * 3 + 4 + Random(strength) + strength / 2 (the half taken of the BCD byte itself, so
; 25 gives 12h = 18: probably meant to use the number). DamageFoe does the rest.
;------------------------------------------------------------------------------
AttackHit:	mov al, byte ptr CombatPlayer	;@8EBC
	mov ah, 40h	;@8EBF
	mul ah	;@8EC1
	mov di, ax	;@8EC3
	lea di, Players[di]	; DI = his record	;@8EC5
	call InExodusCastle	; ZF: Exodus's castle	;@8EC9
	jne AttackHit_Roll	;@8ECC
	cmp byte ptr [di+30h], 0Fh	; Exotic weapon?	;@8ECE
	je AttackHit_Roll	;@8ED2
AttackHit_Miss:	jmp AttackMissed	;@8ED4
AttackHit_Roll:	mov dh, 0FFh	;@8ED6
	call Random	;@8ED8
	shl dl, 1	; half the time a sure hit	;@8EDB
	jb AttackHit_Hit	;@8EDD
	mov dh, 63h	; 0-98 ...	;@8EDF
	call Random	;@8EE1
	mov al, dl	;@8EE4
	aam	; ... as BCD	;@8EE6
	mov cl, 4	;@8EE8
	shl ah, cl	;@8EEA
	or al, ah	;@8EEC
	cmp al, byte ptr [di+13h]	; < dexterity hits	;@8EEE
	jae AttackHit_Miss	;@8EF1
AttackHit_Hit:	mov al, 0	; singular	;@8EF3
	call PrintFoeName	;@8EF5
	lea si, MsgAttackHit	; "Hit!"	;@8EF8
	call PrintMsg	;@8EFC
	mov bp, di	; BP = record	;@8EFF
	mov di, bx	;@8F01
	lea di, StartUp[di]	; DI = StartUp + slot	;@8F03
	mov bh, byte ptr CmbMonY[di]	; foe y	;@8F07
	mov bl, byte ptr Ofs80h[di]	; foe x	;@8F0B
	call ViewTileAt	;@8F0F
	mov ah, al	;@8F12
	mov al, byte ptr HitTile	;@8F14
	mov byte ptr [bx], al	; flash on the foe	;@8F17
	call DrawView	;@8F19
	mov al, 0F7h	;@8F1C
	call Sound	; hit sound	;@8F1E
	mov byte ptr [bx], ah	;@8F21
	mov bx, bp	;@8F23
	mov al, byte ptr [bx+12h]	; strength (BCD) to binary	;@8F25
	mov ah, 0	;@8F28
	mov cl, 4	;@8F2A
	shl ax, cl	;@8F2C
	mov al, byte ptr [bx+12h]	;@8F2E
	and al, 0Fh	;@8F31
	aad	;@8F33
	or al, 1	; Random(strength | 1)	;@8F35
	mov dh, al	;@8F37
	call Random	;@8F39
	mov al, byte ptr [bx+12h]	; + the BCD byte / 2 (+1 if odd)	;@8F3C
	shr al, 1	;@8F3F
	adc dl, al	;@8F41
	mov al, byte ptr [bx+30h]	; weapon readied * 3	;@8F43
	shl al, 1	;@8F46
	add al, byte ptr [bx+30h]	;@8F48
	add al, dl	;@8F4B
	add al, 4	; + 4	;@8F4D
	xchg di, bx	; BX = StartUp + slot, DI = record	;@8F4F
	call DamageFoe	;@8F51
	call DrawView	;@8F54
	jmp PlayerTurnEnd	;@8F57
;------------------------------------------------------------------------------
; DamageFoe: AL damage (binary) to the foe at BX = StartUp + slot; DI = the record of the
; player who gets the experience. Lord British (FoeTile 13h) takes none. At 0 or below: "Killed!
; Exp.+", the foe's tile is replaced by what it stood on, and FoeExp[FoeTile & 0Fh] (BCD) is
; printed and added (ITEMS 5D4B). Also used by MAGIC (5EFC, 5F72). Saves all.
;------------------------------------------------------------------------------
DamageFoe:	pushf	;@8F5A
	push ax	;@8F5B
	push bx	;@8F5C
	push dx	;@8F5D
	push si	;@8F5E
	cmp byte ptr FoeTile, 13h	; Lord British: unhurt	;@8F5F
	je DamageFoe_Done	;@8F64
	mov ah, byte ptr CmbMonHP[bx]	; foe hit points	;@8F66
	sub ah, al	;@8F6A
	mov byte ptr CmbMonHP[bx], ah	;@8F6C
	je DamageFoe_Killed	;@8F70
	jae DamageFoe_Done	;@8F72
DamageFoe_Killed:	lea si, MsgKilledExp	; "Killed! Exp.+"	;@8F74
	call PrintMsg	;@8F78
	mov byte ptr CmbMonHP[bx], 0	; foe hit points = 0: dead	;@8F7B
	mov ah, byte ptr CmbMonUnder[bx]	; tile under the foe	;@8F80
	mov dh, byte ptr CmbMonY[bx]	; foe y	;@8F84
	mov dl, byte ptr Ofs80h[bx]	; foe x	;@8F88
	mov bx, dx	;@8F8C
	call ViewTileAt	;@8F8E
	mov byte ptr [bx], ah	; back on the map	;@8F91
	mov bl, byte ptr FoeTile	;@8F93
	and bl, 0Fh	;@8F97
	mov bh, 0	;@8F9A
	mov al, byte ptr FoeExp[bx]	; the experience it is worth	;@8F9C
	mov dl, al	;@8FA0
	call PrintBcdByte	;@8FA2
	mov bx, di	;@8FA5
	call AddExp	; add AL (BCD) to the record at BX	;@8FA7
	call ScrollMsg	;@8FAA
	call DrawView	;@8FAD
DamageFoe_Done:	pop si	;@8FB0
	pop dx	;@8FB1
	pop bx	;@8FB2
	pop ax	;@8FB3
	popf	;@8FB4
	ret	;@8FB5
;------------------------------------------------------------------------------
; Victory: "****Victory!****", the fanfare, Location as it was (the surface view rebuilt
; outside a dungeon) and back to MainLoop. The chest left where the creature stood is the
; reward.
;------------------------------------------------------------------------------
Victory:	mov byte ptr TimeStop, 0	; Negate Time ends	;@8FB6
	lea si, MsgVictory	;@8FBB
	call PrintMsg	;@8FBF
	call FlushKeys	;@8FC2
	mov al, 0FDh	; warble: the fanfare	;@8FC5
	mov bl, 80h	;@8FC7
	mov bh, 10h	;@8FC9
	call Sound	;@8FCB
	call Sound	;@8FCE
	call Sound	;@8FD1
	mov bl, 60h	;@8FD4
	mov bh, 40h	;@8FD6
	call Sound	;@8FD8
	mov al, byte ptr SavedLocation	; Location before the fight	;@8FDB
	mov byte ptr Location, al	;@8FDE
	cmp al, 1	; a dungeon?	;@8FE1
	je Victory_Done	;@8FE3
	call BuildView	;@8FE5
Victory_Done:	jmp MainLoop	;@8FE8
;------------------------------------------------------------------------------
; FoeCanEnter: AL = the tile at DL, DH -> AL = 0FFh when a foe may step there: sea foes (FoeTile
; 0Bh-0Fh) on water only, the others on grass, brush, forest or floor, and no live foe there;
; else AL = 0. Saves flags, BX.
;------------------------------------------------------------------------------
FoeCanEnter:	pushf	;@8FEB
	push bx	;@8FEC
	cmp byte ptr FoeTile, 10h	; sea foe (0Bh-0Fh)?	;@8FED
	jae FoeCanEnter_Land	;@8FF2
	cmp byte ptr FoeTile, 0Bh	;@8FF4
	jb FoeCanEnter_Land	;@8FF9
	cmp al, 0	; water?	;@8FFB
	jne FoeCanEnter_No	;@8FFD
FoeCanEnter_Free:	mov al, 0FFh	;@8FFF
	call FindFoeAt	; a foe there?	;@9001
	cmp bx, -1	;@9004
	jne FoeCanEnter_No	;@9007
FoeCanEnter_Done:	pop bx	;@9009
	popf	;@900A
	ret	;@900B
FoeCanEnter_Land:	cmp al, 1	; grass	;@900C
	je FoeCanEnter_Free	;@900E
	cmp al, 2	; brush	;@9010
	je FoeCanEnter_Free	;@9012
	cmp al, 3	; forest	;@9014
	je FoeCanEnter_Free	;@9016
	cmp al, 8	; floor	;@9018
	je FoeCanEnter_Free	;@901A
FoeCanEnter_No:	mov al, 0	;@901C
	jmp FoeCanEnter_Done	;@901E
;------------------------------------------------------------------------------
; FoeChooseMove: for foe DI (0-7) look at each player who is up. A player next to it (diagonals
; too): AL = 0, BX = that player. Otherwise for the nearest player (|dx| + |dy|; ties go to the
; later one) a step towards him that FoeCanEnter allows: diagonal, else vertical, else
; horizontal. Out: AL = that distance (0FFh: no step), BX = the player (0FFFFh none), CX = the
; step (CL x, CH y), DX = the cell. Locals: [bp] record, [bp+2] step, [bp+4] cell (DX is left
; from the stack when no step was found).
;------------------------------------------------------------------------------
FoeChooseMove:	pushf	;@9020
	push bp	;@9021
	sub sp, 2	;@9022
	sub sp, 2	;@9025
	sub sp, 2	;@9028
	mov bp, sp	;@902B
	push si	;@902D
	mov si, 0FFFFh	; SI = the player chosen: none	;@902E
	lea bx, Players	;@9031
	mov word ptr [bp], bx	; [bp] = record pointer	;@9035
	mov bx, 0	; BX = player number	;@9038
	mov ah, 0FFh	; AH = best distance so far	;@903B
FoeChoose_Loop:	xchg word ptr [bp], bx	;@903D
	call IsUp	;@9040
	xchg word ptr [bp], bx	;@9043
	je FoeChoose_Dist	;@9046
	jmp FoeChoose_Next	;@9048
FoeChoose_Dist:	mov dl, byte ptr StartUp+0A0h[bx]	; player x ...	;@904B
	sub dl, byte ptr StartUp+80h[di]	; ... - foe x	;@904F
	mov cl, dl	;@9053
	test cl, 0FFh	;@9055
	jns FoeChoose_AbsY	;@9058
	neg cl	;@905A
FoeChoose_AbsY:	mov dh, byte ptr StartUp+0A4h[bx]	; player y ...	;@905C
	sub dh, byte ptr StartUp+88h[di]	; ... - foe y	;@9060
	mov ch, dh	;@9064
	test ch, 0FFh	;@9066
	jns FoeChoose_Near	;@9069
	neg ch	;@906B
FoeChoose_Near:	mov al, cl	;@906D
	or al, ch	; adjacent: both 1 or less	;@906F
	cmp al, 1	;@9071
	ja FoeChoose_TryStep	;@9073
	jmp FoeChoose_Adjacent	;@9075
FoeChoose_TryStep:	mov al, cl	; |dx| + |dy|	;@9078
	add al, ch	;@907A
	cmp al, ah	; no nearer than the best	;@907C
	ja FoeChoose_Next	;@907E
	push ax	;@9080
	push bx	;@9081
	mov al, dl	;@9082
	call SignStep	; AH = -1, 0, 1 (library)	;@9084
	mov cl, ah	;@9087
	mov al, dh	;@9089
	call SignStep	;@908B
	mov ch, ah	;@908E
	mov dl, byte ptr StartUp+80h[di]	; diagonal step	;@9090
	mov dh, byte ptr StartUp+88h[di]	;@9094
	add dl, cl	;@9098
	add dh, ch	;@909A
	mov bx, dx	;@909C
	call ViewTileAt	;@909E
	call FoeCanEnter	; allowed?	;@90A1
	cmp al, 0FFh	;@90A4
	je FoeChoose_Keep	;@90A6
	mov dl, byte ptr StartUp+80h[di]	; vertical: foe x, y + step	;@90A8
	mov bx, dx	;@90AC
	call ViewTileAt	;@90AE
	call FoeCanEnter	;@90B1
	cmp al, 0FFh	;@90B4
	je FoeChoose_Keep	;@90B6
	add dl, cl	; horizontal: x + step, foe y	;@90B8
	mov dh, byte ptr StartUp+88h[di]	;@90BA
	mov bx, dx	;@90BE
	call ViewTileAt	;@90C0
	call FoeCanEnter	;@90C3
	cmp al, 0FFh	;@90C6
	je FoeChoose_Keep	;@90C8
	pop bx	;@90CA
	pop ax	;@90CB
	jmp short FoeChoose_Next	;@90CC
FoeChoose_Keep:	pop bx	;@90CE
	pop ax	;@90CF
	mov ah, al	; the new best	;@90D0
	mov si, bx	;@90D2
	mov word ptr [bp+2], cx	; step	;@90D4
	mov word ptr [bp+4], dx	; cell	;@90D7
FoeChoose_Next:	inc bx	;@90DA
	add word ptr [bp], 40h	;@90DB
	cmp bl, byte ptr PartySize	;@90DF
	jae FoeChoose_End	;@90E3
	jmp FoeChoose_Loop	;@90E5
FoeChoose_End:	mov al, ah	; AL = best distance	;@90E8
	mov bx, si	;@90EA
FoeChoose_Ret:	mov cx, word ptr [bp+2]	;@90EC
	mov dx, word ptr [bp+4]	;@90EF
	pop si	;@90F2
	add sp, 6	;@90F3
	pop bp	;@90F6
	popf	;@90F7
	ret	;@90F8
FoeChoose_Adjacent:	mov al, 0	; adjacent: AL = 0, BX = player	;@90F9
	jmp FoeChoose_Ret	;@90FB
;------------------------------------------------------------------------------
; FoeBreathe: a dragon's fire from foe DI along CL, CH: the fall sound, a fire tile (3Dh)
; moving cell by cell until it meets a player (FoeHurtPlayer) or leaves the map. Saves all.
;------------------------------------------------------------------------------
FoeBreathe:	pushf	;@90FD
	push ax	;@90FE
	push bx	;@90FF
	push dx	;@9100
	mov al, 0FBh	; fall sound	;@9101
	call Sound	;@9103
	mov dl, byte ptr StartUp+80h[di]	; from the foe's x ...	;@9106
	mov dh, byte ptr StartUp+88h[di]	; ... and y	;@910A
FoeBreathe_Step:	add dl, cl	;@910E
	cmp dl, 0Bh	;@9110
	jae FoeBreathe_Done	;@9113
	add dh, ch	;@9115
	cmp dh, 0Bh	;@9117
	jae FoeBreathe_Done	;@911A
	mov al, byte ptr PartySize	;@911C
	mov ah, 0	;@911F
	dec ax	;@9121
	mov bx, ax	;@9122
FoeBreathe_Plr:	cmp dl, byte ptr StartUp+0A0h[bx]	; player x?	;@9124
	jne FoeBreathe_NextPlr	;@9128
	cmp dh, byte ptr StartUp+0A4h[bx]	; player y?	;@912A
	jne FoeBreathe_NextPlr	;@912E
	call FoeHurtPlayer	; BX = the player hit	;@9130
	jmp short FoeBreathe_Done	;@9133
FoeBreathe_NextPlr:	dec bx	;@9135
	jns FoeBreathe_Plr	;@9136
	mov bx, dx	;@9138
	call ViewTileAt	;@913A
	mov byte ptr [bx], 3Dh	; the flame	;@913D
	call DrawView	;@9140
	mov byte ptr [bx], al	;@9143
	jmp FoeBreathe_Step	;@9145
FoeBreathe_Done:	call DrawView	;@9147
	pop dx	;@914A
	pop bx	;@914B
	pop ax	;@914C
	popf	;@914D
	ret	;@914E
;------------------------------------------------------------------------------
; FoesTurn: while Negate Time runs (TimeStop) the foes miss the round. Else each live foe in
; turn: next to a player it attacks; a Dragon breathes fire half the time it has a target; one
; time in three the casters (Serpent, Man-O-War, Wizard, Daemon, Dragon, Balron) strike a random
; player 0-3 with magic, if his status is Good (a poisoned player is safe from it); otherwise it
; steps towards the nearest player. Then the next round.
;------------------------------------------------------------------------------
FoesTurn:	cmp byte ptr TimeStop, 0	;@914F
	je FoesTurn_Start	;@9154
	dec byte ptr TimeStop	; one round less	;@9156
	jmp FoesTurn_Done	;@915A
FoesTurn_Start:	mov di, 0	;@915D
FoesTurn_Loop:	cmp byte ptr StartUp+98h[di], 0	; foe hit points: alive?	;@9160
	jne FoesTurn_Alive	;@9165
	jmp FoesTurn_Next	;@9167
FoesTurn_Alive:	call FoeChooseMove	; AL = distance, BX = player, CX step, DX cell	;@916A
	mov byte ptr HitTile, 3Dh	; HitTile = fire	;@916D
	cmp al, 0	; adjacent?	;@9172
	jne FoesTurn_TryBreath	;@9174
	call FoeAttack	; attack player BL	;@9176
	jmp FoesTurn_Next	;@9179
FoesTurn_TryBreath:	cmp bx, -1	; a target?	;@917C
	je FoesTurn_TryMagic	;@917F
	push dx	;@9181
	mov dh, 0FFh	;@9182
	call Random	;@9184
	shl dl, 1	; half the time	;@9187
	pop dx	;@9189
	jb FoesTurn_TryMagic	;@918A
	cmp byte ptr FoeTile, 1Dh	; Dragon?	;@918C
	jne FoesTurn_TryMagic	;@9191
	call FoeBreathe	; breathe along CX	;@9193
	jmp short FoesTurn_Next	;@9196
FoesTurn_TryMagic:	push dx	;@9198
	mov dh, 0C0h	; Random(0C0h) ...	;@9199
	call Random	;@919B
	shl dl, 1	; ... >= 80h: one time in 3	;@919E
	pop dx	;@91A0
	jae FoesTurn_Move	;@91A1
	mov ah, byte ptr FoeTile	;@91A3
	cmp ah, 0Dh	; Serpent	;@91A7
	je FoesTurn_Magic	;@91AA
	cmp ah, 0Eh	; Man-O-War	;@91AC
	je FoesTurn_Magic	;@91AF
	cmp ah, 16h	; Wizard	;@91B1
	je FoesTurn_Magic	;@91B4
	cmp ah, 1Bh	; Daemon	;@91B6
	je FoesTurn_Magic	;@91B9
	cmp ah, 1Dh	; Dragon	;@91BB
	je FoesTurn_Magic	;@91BE
	cmp ah, 1Eh	; Balron	;@91C0
	je FoesTurn_Magic	;@91C3
	cmp ah, 13h	; Lord British: steps even with no step found	;@91C5
	je FoesTurn_Step	;@91C8
FoesTurn_Move:	test al, 0FFh	; no step (AL = 0FFh): stays	;@91CA
	js FoesTurn_Next	;@91CC
FoesTurn_Step:	call FoeStep	;@91CE
	jmp short FoesTurn_Next	;@91D1
FoesTurn_Magic:	push dx	;@91D3
	mov dh, 0FFh	;@91D4
	call Random	;@91D6
	and dl, 3	; a player 0-3 (not PartySize)	;@91D9
	mov bl, dl	;@91DC
	pop dx	;@91DE
	mov bh, 0	;@91DF
	push ax	;@91E1
	mov al, 40h	;@91E2
	mul bl	;@91E4
	mov si, ax	;@91E6
	cmp byte ptr PlrStatus[si], 47h	; status (Players + 11h)	;@91E8
	pop ax	;@91ED
	jne FoesTurn_Move	; not Good: move instead	;@91EE
	push bx	;@91F0
	call FlashView	; flash the screen	;@91F1
	mov bl, 40h	;@91F4
	mov bh, 40h	;@91F6
	mov al, 0FDh	; warble	;@91F8
	call Sound	;@91FA
	call FlashView	;@91FD
	pop bx	;@9200
	mov byte ptr HitTile, 3Ch	; HitTile = magic	;@9201
	call FoeAttack	; attack player BL	;@9206
FoesTurn_Next:	inc di	;@9209
	cmp di, 8	;@920A
	je FoesTurn_Done	;@920D
	jmp FoesTurn_Loop	;@920F
FoesTurn_Done:	jmp CombatRound	;@9212
;------------------------------------------------------------------------------
; FoeStep: move foe DI to the cell DX: the tile it covered goes back, it covers the new one.
; Saves AX, BX (not the flags).
;------------------------------------------------------------------------------
FoeStep:	push ax	;@9215
	push bx	;@9216
	mov bh, byte ptr StartUp+88h[di]	; foe y	;@9217
	mov bl, byte ptr StartUp+80h[di]	; foe x	;@921B
	call ViewTileAt	;@921F
	mov al, byte ptr StartUp+90h[di]	; tile under the foe back	;@9222
	mov byte ptr [bx], al	;@9226
	mov byte ptr StartUp+80h[di], dl	; foe x	;@9228
	mov byte ptr StartUp+88h[di], dh	; foe y	;@922C
	mov bx, dx	;@9230
	call ViewTileAt	;@9232
	mov byte ptr StartUp+90h[di], al	; the new tile under it	;@9235
	mov al, byte ptr FoeTile	;@9239
	mov byte ptr [bx], al	; draw the foe	;@923C
	call DrawView	;@923E
	pop bx	;@9241
	pop ax	;@9242
	ret	;@9243
;------------------------------------------------------------------------------
; FoeAttack: a foe attacks player BL (0-3). Man-O-War, Balron and Pincher may poison and
; Thieves steal first (whether the blow hits or not). "Plr n", then the blow hits when
; Random(armour + 16) < 8 (half with Skin, 8 in 23 with Exotic); in the castle of Exodus it
; always hits unless the player wears Exotic armour. " Hit!" (FoeHurtPlayer) or " Missed!".
; Saves flags, AX, SI.
;------------------------------------------------------------------------------
FoeAttack:	pushf	;@9244
	push ax	;@9245
	push si	;@9246
	mov al, byte ptr FoeTile	;@9247
	cmp al, 0Eh	; Man-O-War	;@924A
	je FoeAttack_Poison	;@924C
	cmp al, 1Eh	; Balron	;@924E
	je FoeAttack_Poison	;@9250
	cmp al, 1Ch	; Pincher	;@9252
	jne FoeAttack_TryThief	;@9254
FoeAttack_Poison:	call FoePoison	; may poison	;@9256
	jmp short FoeAttack_Roll	;@9259
FoeAttack_TryThief:	cmp al, 17h	; Thief?	;@925B
	jne FoeAttack_Roll	;@925D
	call FoeSteal	; may steal	;@925F
FoeAttack_Roll:	lea si, MsgPlrN	; "Plr "	;@9262
	call PrintMsg	;@9266
	mov al, bl	;@9269
	add al, 31h	; '1' + player	;@926B
	call PutChar	;@926D
	mov al, 0F8h	; noise-rise sound	;@9270
	call Sound	;@9272
	mov al, 40h	;@9275
	mul bl	;@9277
	mov si, ax	;@9279
	lea si, Players[si]	;@927B
	call InExodusCastle	; ZF: Exodus's castle	;@927F
	jne FoeAttack_Armour	;@9282
	cmp byte ptr [si+28h], 7	; Exotic armour?	;@9284
	jne FoeAttack_Hit	;@9288
FoeAttack_Armour:	mov dh, byte ptr [si+28h]	; armour worn + 16	;@928A
	add dh, 10h	;@928D
	call Random	;@9290
	cmp dl, 8	; 7 or less: hit	;@9293
	jb FoeAttack_Hit	;@9296
	lea si, MsgFoeMissed	; " Missed!"	;@9298
	call PrintMsg	;@929C
	jmp short FoeAttack_Done	;@929F
FoeAttack_Hit:	lea si, MsgFoeHit	; " Hit!"	;@92A1
	call PrintMsg	;@92A5
	call FoeHurtPlayer	;@92A8
FoeAttack_Done:	pop si	;@92AB
	pop ax	;@92AC
	popf	;@92AD
	ret	;@92AE
;------------------------------------------------------------------------------
; FoeHurtPlayer: damage player BL (0-3): Random(FoeHitPoints[FoeTile & 0Fh] / 8 + the high byte
; of his max hit points, | 1) + 1, as BCD, then 10 more for each step of the old Location & 3
; (dungeon 10, town 20, castle and Ambrosia 30). A flash, and at status 'D' the player leaves
; the map: "Killed!!!" (PARTY 6C29 ends the game when nobody is left). Saves all.
;------------------------------------------------------------------------------
FoeHurtPlayer:	pushf	;@92AF
	push ax	;@92B0
	push bx	;@92B1
	push cx	;@92B2
	push dx	;@92B3
	push si	;@92B4
	mov si, bx	; SI = player number	;@92B5
	mov al, 40h	;@92B7
	mul bl	;@92B9
	mov bx, ax	;@92BB
	lea bx, Players[bx]	;@92BD
	mov dx, bx	; DX = his record	;@92C1
	mov bl, byte ptr FoeTile	;@92C3
	mov bh, 0	;@92C7
	and bl, 0Fh	;@92C9
	mov al, byte ptr FoeHitPoints[bx]	;@92CC
	mov bx, dx	;@92D0
	shr al, 1	; the foe's hit point range / 8	;@92D2
	shr al, 1	;@92D4
	shr al, 1	;@92D6
	add al, byte ptr [bx+1Dh]	; + max hit points, high byte (BCD)	;@92D8
	or al, 1	;@92DB
	mov dh, al	;@92DD
	call Random	;@92DF
	add dl, 1	; 1 ...	;@92E2
	mov al, dl	;@92E5
	aam	; ... as BCD	;@92E7
	mov cl, 4	;@92E9
	shl ah, cl	;@92EB
	or al, ah	;@92ED
	call HurtPlayer	; subtract from his hit points	;@92EF
	mov al, byte ptr SavedLocation	; the Location before the fight	;@92F2
	and al, 3	;@92F5
	shl al, cl	; 0, 10, 20, 30 (BCD)	;@92F7
	call HurtPlayer	; subtract that too	;@92F9
	mov ax, si	;@92FC
	call FlashPlayer	; flash his status line	;@92FE
	mov dx, bx	;@9301
	mov bl, byte ptr StartUp+0A0h[si]	; player x	;@9303
	mov bh, byte ptr StartUp+0A4h[si]	; player y	;@9307
	call ViewTileAt	;@930B
	mov al, byte ptr HitTile	;@930E
	mov byte ptr [bx], al	; flash on him	;@9311
	call DrawView	;@9313
	mov al, 0F7h	;@9316
	call Sound	; hit sound	;@9318
	mov al, byte ptr StartUp+0ACh[si]	; his tile back	;@931B
	mov byte ptr [bx], al	;@931F
	call DrawView	;@9321
	mov ax, si	;@9324
	call FlashPlayer	;@9326
	mov bx, dx	;@9329
	cmp byte ptr [bx+11h], 44h	; status 'D' dead?	;@932B
	jne FoeHurtPlayer_Done	;@932F
	mov bl, byte ptr StartUp+0A0h[si]	;@9331
	mov bh, byte ptr StartUp+0A4h[si]	;@9335
	call ViewTileAt	;@9339
	mov al, byte ptr StartUp+0A8h[si]	; the tile he stood on	;@933C
	mov byte ptr [bx], al	;@9340
	mov byte ptr StartUp+0A0h[si], 0FFh	; player x, y = 0FFh: off the map	;@9342
	mov byte ptr StartUp+0A4h[si], 0FFh	;@9347
	lea si, MsgPlrKilled	; "Killed!!!"	;@934C
	call PrintMsg	;@9350
	call CheckAllOut	; all dead? (does not come back then)	;@9353
FoeHurtPlayer_Done:	call StatusLine	;@9356
	pop si	;@9359
	pop dx	;@935A
	pop cx	;@935B
	pop bx	;@935C
	pop ax	;@935D
	popf	;@935E
	ret	;@935F
;------------------------------------------------------------------------------
; FoePoison: one time in 4 a Good player BL becomes Poisoned: "Plr n Poisoned!". Saves all.
;------------------------------------------------------------------------------
FoePoison:	pushf	;@9360
	push ax	;@9361
	push dx	;@9362
	push si	;@9363
	mov dh, 0FFh	;@9364
	call Random	;@9366
	and dl, 3	;@9369
	jne FoePoison_Done	;@936C
	mov al, 40h	;@936E
	mul bl	;@9370
	mov si, ax	;@9372
	cmp byte ptr PlrStatus[si], 47h	; status (Players + 11h) 'G'?	;@9374
	jne FoePoison_Done	;@9379
	mov byte ptr PlrStatus[si], 50h	; 'P'	;@937B
	lea si, MsgPlrN	;@9380
	call PrintMsg	;@9384
	mov al, bl	;@9387
	add al, 31h	;@9389
	call PutChar	;@938B
	lea si, MsgPlrPoisoned	; " Poisoned!"	;@938E
	call PrintMsg	;@9392
	mov al, 0FAh	; rise sound	;@9395
	call Sound	;@9397
	call StatusLine	;@939A
FoePoison_Done:	pop si	;@939D
	pop dx	;@939E
	pop ax	;@939F
	popf	;@93A0
	ret	;@93A1
;------------------------------------------------------------------------------
; FoeSteal: a thief robs player BL: half the time a weapon kind 1-15, else an armour kind 1-7,
; at random; if he has one and it is not the one readied or worn, one fewer: "Plr n Pilfered!".
; Saves all.
;------------------------------------------------------------------------------
FoeSteal:	pushf	;@93A2
	push ax	;@93A3
	push bx	;@93A4
	push dx	;@93A5
	push si	;@93A6
	push di	;@93A7
	mov al, 40h	;@93A8
	mul bl	;@93AA
	mov si, ax	;@93AC
	lea si, Players[si]	;@93AE
	mov di, bx	; DI = player number	;@93B2
	mov dh, 0FFh	;@93B4
	call Random	;@93B6
	rol dl, 1	;@93B9
	jb FoeSteal_Armour	;@93BB
	mov dh, 10h	; a weapon kind 0-15	;@93BD
